export const getReferenceDemographic = id => DEMOGRAPHICS[id] ?? null;
export function referenceDistribution(countries, weighting='birth') {
  if(!['birth','population'].includes(weighting))throw new TypeError('Unknown reference weighting');
  const field=weighting==='birth'?'estimatedBirths':'population';
  const rows=countries.map(country=>({countryId:country.id,weight:DEMOGRAPHICS[country.id]?.[field]??null})).filter(row=>Number.isFinite(row.weight)&&row.weight>0);
  const total=rows.reduce((sum,row)=>sum+row.weight,0);
  return rows.map(row=>Object.freeze({...row,share:row.weight/total,year:DEMOGRAPHIC_META.year,source:DEMOGRAPHIC_META.id}));
}
export function referenceCoverage(countries) {
  const population=new Set(referenceDistribution(countries,'population').map(row=>row.countryId));
  const birth=new Set(referenceDistribution(countries,'birth').map(row=>row.countryId));
  return {year:DEMOGRAPHIC_META.year,populationCount:population.size,birthCount:birth.size,missingPopulation:countries.filter(c=>!population.has(c.id)).map(c=>c.id),missingBirth:countries.filter(c=>!birth.has(c.id)).map(c=>c.id)};
}
